from __future__ import annotations

from typing import TYPE_CHECKING

import pytest

if TYPE_CHECKING:
    from tests.services.ui.e2e.conftest import App


@pytest.mark.smoke
def test_the_app_loads_and_the_bottom_bar_shows_and_hides_panels(app: App) -> None:
    assert app.shown() == ["chat"]
    app.show("chat", "python", "terminal")
    assert app.shown() == ["chat", "python", "terminal"]
    app.show("python")
    assert app.shown() == ["python"]


@pytest.mark.smoke
def test_alt_right_into_the_terminal_types_in_the_shell(app: App) -> None:
    # the bug: the cursor moved to the Terminal but the shell didn't get the keys
    app.show("python", "terminal")
    app.page.click(".cell .cm-content")
    app.page.keyboard.press("Alt+ArrowRight")
    app.wait_terminal_focus(focused=True)
    assert app.active() == "terminal"
    app.page.keyboard.type("echo from-python")
    app.wait_terminal_text("echo from-python")


def test_alt_arrows_go_round_the_panels_shown_from_inside_the_terminal_too(app: App) -> None:
    app.show("chat", "python", "terminal")
    app.page.click(".cell .cm-content")
    seen = []
    for _ in range(3):
        app.page.keyboard.press("Alt+ArrowRight")  # from the shell too: its page hands the key back
        app.page.wait_for_timeout(400)
        seen.append(app.active())
    assert seen == ["terminal", "chat", "python"]
    app.page.keyboard.press("Alt+ArrowLeft")
    app.page.wait_for_timeout(400)
    assert app.active() == "chat"


def test_the_terminals_cursor_only_blinks_while_you_are_in_it(app: App) -> None:
    app.show("python", "terminal")
    cursor = "() => window.smashTerminal.cursor()"
    app.page.click('[data-pane="terminal"] iframe')
    app.wait_terminal_focus(focused=True)
    assert app.terminal().evaluate(cursor) == {"blink": True, "style": "block"}
    app.page.keyboard.press("Alt+ArrowLeft")
    app.wait_terminal_focus(focused=False)
    assert app.terminal().evaluate(cursor) == {"blink": False, "style": "underline"}
    app.page.keyboard.press("Alt+ArrowRight")
    app.wait_terminal_focus(focused=True)
    assert app.terminal().evaluate(cursor) == {"blink": True, "style": "block"}


def test_what_you_type_in_one_panel_stays_out_of_the_other(app: App) -> None:
    app.show("python", "terminal")
    app.page.click(".cell .cm-content")
    app.page.keyboard.type("in_the_cell")
    app.page.keyboard.press("Alt+ArrowRight")
    app.wait_terminal_focus(focused=True)
    app.page.keyboard.type("in_the_shell")
    app.wait_terminal_text("in_the_shell")
    assert "in_the_cell" not in app.terminal_text()
    assert app.page.locator(".cell .cm-content").first.inner_text().strip() == "in_the_cell"


def test_alt_t_in_results_opens_the_new_tab_menu_and_enter_adds_one(app: App) -> None:
    app.show("chat", "results")
    app.chat_box.click()
    assert app.active() == "chat"
    app.page.keyboard.press("Alt+T")  # the cursor is in the chat: nothing opens
    app.page.wait_for_timeout(300)  # a menu would be open by now (no condition to wait for)
    assert not app.page.locator(".menu-search").is_visible()
    app.page.keyboard.press("Alt+ArrowRight")
    assert app.active() == "results"
    app.page.keyboard.press("Alt+T")
    search = app.page.locator(".menu-search")
    search.wait_for()
    search.type("smashdb")  # the box has the cursor: typing filters the widgets
    search.press("Enter")
    app.page.locator('[data-pane="results"] .widget .db-console').wait_for()
